import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        num_groups = int(next(iterator))
    except StopIteration:
        return

    for _ in range(num_groups):
        try:
            num_friends = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(num_friends + 1)]

        for i in range(1, num_friends + 1):
            line_parts = []
            while True:
                try:
                    token = next(iterator)
                    line_parts.append(token)
                except StopIteration:
                    break
                if len(line_parts) > 0:
                    pass

            if not line_parts:
                continue

            friends_list = [int(x) for x in line_parts]
            for friend in friends_list:
                adj[i].append(friend)
                adj[friend].append(i)

        def bfs_distances(start_node, n_nodes, graph):
            dist = [-1] * (n_nodes + 1)
            dist[start_node] = 0
            queue = deque([start_node])

            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        queue.append(v)
            return dist[1:]

        min_notoriety = float('inf')
        best_friend = -1

        for i in range(1, num_friends + 1):
                dists = bfs_distances(i, num_friends, adj)
                total_dist = sum(dists)
                notoriety = total_dist / num_friends

                if notoriety < min_notoriety:
                    min_notoriety = notoriety
                    best_friend = i
                elif notoriety == min_notoriety:
                    if i < best_friend:
                        best_friend = i

        final_dists = bfs_distances(best_friend, num_friends, adj)
        avg_dist = sum(final_dists) / num_friends

        print(f"{best_friend} {avg_dist:.6f}")

if __name__ == "__main__":
    solve()
